/* Explicit manual cusp inputs. Approved worksheet and ephemeris formulas are untouched. */
(()=>{'use strict';const $=id=>document.getElementById(id),R=['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'];let manual=null,selected=0,dialog;
function signature(){return JSON.stringify(['dob','birthTime','lat','lon','birth-utc-offset','birth-dst-minutes','instant-prashna'].map(id=>[id,$(id)?.value]));}
function active(){return manual&&manual.signature===signature();}
function validate(values){if(!Array.isArray(values)||values.length!==12||values.some(n=>!Number.isInteger(n)||n<0||n>=1296000))throw Error('Enter twelve valid cusp positions from 0° to 359°59′59″.');const gaps=values.map((n,i)=>(values[(i+1)%12]-n+1296000)%1296000);if(gaps.some(n=>n===0)||gaps.reduce((a,b)=>a+b,0)!==1296000)throw Error('Cusps must follow I–XII in zodiac order, without duplicates.');return values.slice();}
const originalSync=window.syncKPWorksheetPositions;
window.syncKPWorksheetPositions=function(...args){const data=originalSync.apply(this,args);if(active()){data.cusps=manual.cusps.slice();window.cuspResults=data.cusps.map((nir,i)=>({i:i+1,nir,rashi:['मेष','वृषभ','मिथुन','कर्क','सिंह','कन्या','तुळ','वृश्चिक','धनु','मकर','कुंभ','मीन'][Math.floor(nir/108000)]}));}return data;};
function status(){document.querySelectorAll('[data-cusp-mode]').forEach(n=>n.textContent=active()?'Manual cusp positions applied':'Automatic calculated cusps');}
function refresh(){window.kundaliManual=false;window.updateKaryeshTables?.();window.renderChart?.(true);window.KPChartStyle?.refresh();window.refreshHomeDashboard?.();window.KPHomeDashboard?.refresh();status();window.dispatchEvent(new Event('chart-manual-change'));}
function apply(cusps){manual={version:1,signature:signature(),cusps:validate(cusps)};refresh();}
function reset(){manual=null;refresh();}
const oldSave=window.getChartData;if(oldSave)window.getChartData=function(...args){const data=oldSave.apply(this,args);if(active())data.manualCuspOverrides=structuredClone(manual);return data;};
const oldRestore=window.restoreChartData;if(oldRestore)window.restoreChartData=function(data,...args){const saved=data?.manualCuspOverrides;if(saved)validate(saved.cusps);manual=null;const result=oldRestore.call(this,data,...args);if(saved){manual={version:1,signature:signature(),cusps:saved.cusps.slice()};refresh();}else status();return result;};
function format(value){const n=Math.round(value);return [Math.floor(n/3600),Math.floor(n%3600/60),n%60].map((v,i)=>i?String(v).padStart(2,'0'):v).join(':');}
function read(value){const parts=value.trim().split(/[:°′″\s]+/).filter(Boolean).map(Number);if(parts.length!==3||parts.some(n=>!Number.isInteger(n))||parts[0]<0||parts[0]>=360||parts[1]<0||parts[1]>=60||parts[2]<0||parts[2]>=60)throw Error('Use degrees:minutes:seconds, for example 192:56:42.');return parts[0]*3600+parts[1]*60+parts[2];}
function open(){if(!dialog){dialog=document.createElement('dialog');dialog.className='kp-cusp-dialog';dialog.innerHTML='<form method="dialog"><header><h2>Cusp Setting Tool</h2><button aria-label="Close">×</button></header></form><p>Manual changes affect charts and significators. Automatic calculation formulas are preserved.</p><div class="kp-cusp-picker"></div><div class="kp-cusp-fields"></div><p role="status" data-cusp-feedback></p><footer><button type="button" data-apply>Apply manual cusps</button><button type="button" data-reset>Restore automatic cusps</button><button type="button" data-close>Close</button></footer>';document.body.append(dialog);const picker=dialog.querySelector('.kp-cusp-picker'),fields=dialog.querySelector('.kp-cusp-fields');R.forEach((name,i)=>{const b=document.createElement('button');b.textContent=name;b.type='button';b.onclick=()=>{selected=i;fields.children[i].querySelector('input').focus();};picker.append(b);const label=document.createElement('label');label.textContent='Cusp '+name+' · D:M:S';const input=document.createElement('input');input.dataset.cuspIndex=i;input.inputMode='text';input.autocomplete='off';label.append(input);fields.append(label);});dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelector('[data-reset]').onclick=()=>{reset();fill();dialog.querySelector('[data-cusp-feedback]').textContent='Automatic calculated cusps restored.';};dialog.querySelector('[data-apply]').onclick=()=>{try{apply([...fields.querySelectorAll('input')].map(n=>read(n.value)));dialog.querySelector('[data-cusp-feedback]').textContent='Manual cusps applied. Use Save to include them in your chart backup.';}catch(e){dialog.querySelector('[data-cusp-feedback]').textContent=e.message;}};}
fill();dialog.showModal();dialog.querySelectorAll('input')[selected].focus();}
function fill(){const values=active()?manual.cusps:originalSync().cusps;dialog.querySelectorAll('input').forEach((n,i)=>n.value=Number.isFinite(values[i])?format(values[i]):'');}
function init(){const bar=document.querySelector('#south9 .kundali-toolbar');if(bar&&!bar.querySelector('[data-cusp-tool]')){const update=document.createElement('button');update.textContent='Update Chart';update.onclick=refresh;const cusp=document.createElement('button');cusp.textContent='Cusp Setting Tool';cusp.dataset.cuspTool='';cusp.onclick=open;const save=document.createElement('button');save.textContent='Save';save.onclick=()=>document.querySelector('[data-action="save-kundali"]')?.click();const note=document.createElement('span');note.dataset.cuspMode='';bar.append(update,cusp,save,note);}status();}
window.KPManualCusps=Object.freeze({open,apply,reset,get:()=>active()?structuredClone(manual):null,validate});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();
